<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { KeyRound, ShieldCheck, SlidersHorizontal, Plus, Search, RotateCcw, UserRound, LockKeyhole, ArrowRight } from '@lucide/vue'
import CenterLayout from './CenterLayout.vue'
import PackageEditor from './PackageEditor.vue'
import GrantChangePreview from './GrantChangePreview.vue'
import { modeLabel, packageLabel, statusLabel, type CapabilityGroup, type ChangePreview, type Grant, type LicensePackage } from './types'
type State = { grants: Grant[]; packages: LicensePackage[]; capabilityGroups: CapabilityGroup[]; notices: { id: string; grantId: string; grantName?: string; cancelledAt?: number; days: number; expiresAt: string; deliveredAt?: number; lastError?: string }[]; audit: { id: string; event: string; actor: string; target: string; at: number; eventLabel: string; actorLabel: string; targetLabel: string; description: string }[] }
const token = ref(''), busy = ref(false), error = ref(''), success = ref(''), secretResult = ref(''), page = ref('grants')
const state = ref<State>({ grants: [], packages: [], capabilityGroups: [], audit: [], notices: [] }), login = reactive({ username: '', password: '', code: '', challengeId: '', captchaAnswer: '' })
const loginMode = ref<'' | 'totp' | 'captcha'>(''), captchaImage = ref('')
const issue = reactive({ name: '', domain: '', modelMode: 'fixed', packageKey: 'standard:1', expiresAt: '' })
const selected = ref<Grant | null>(null), change = reactive({ status: 'enabled', expiresAt: '', modelMode: 'fixed', packageKey: '', neverExpires: false }), managementDialog = ref<HTMLDialogElement | null>(null)
const impact = ref<ChangePreview | null>(null), pendingPatch = ref<Record<string, unknown>>({})
watch(change, () => { impact.value = null; pendingPatch.value = {} }, { deep: true, flush: 'sync' })
watch(selected, async grant => { if (grant) { await nextTick(); managementDialog.value?.showModal() } })
const showIssue = ref(false), issueDialog = ref<HTMLDialogElement | null>(null), search = ref(''), statusFilter = ref('all')
watch(showIssue, async open => { if (open) { await nextTick(); issueDialog.value?.showModal() } })
const visibleGrants = computed(() => state.value.grants.filter(g => { const status = g.status === 'enabled' && g.expiresAt && Date.parse(g.expiresAt) <= Date.now() ? 'expired' : g.status; return (statusFilter.value === 'all' || status === statusFilter.value) && `${g.name} ${g.id} ${g.domain}`.toLowerCase().includes(search.value.trim().toLowerCase()) }))
const rowAction = ref<{ grant: Grant; type: 'suspend' | 'enable' | 'delete' } | null>(null), actionDialog = ref<HTMLDialogElement | null>(null)
watch(rowAction, async action => { if (action) { await nextTick(); actionDialog.value?.showModal() } })
const migration = reactive({ instanceId: '', domain: '', overlapHours: 0 })
const counts = computed(() => ({ total: state.value.grants.length, enabled: state.value.grants.filter(g => g.status === 'enabled' && (!g.expiresAt || Date.parse(g.expiresAt) > Date.now())).length, fixed: state.value.grants.filter(g => g.modelMode === 'fixed').length }))
async function request<T>(path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST'): Promise<T> {
  const response = await fetch('/api/license-center/v1/operator' + path, { method, redirect: 'error', headers: { 'Content-Type': 'application/json', ...(token.value ? { Authorization: `Bearer ${token.value}` } : {}) }, ...(body === undefined ? {} : { body: JSON.stringify(body) }), signal: AbortSignal.timeout(15000) })
  const payload = await response.json(); if (!response.ok || payload.success === false) { if (response.status === 401 && path !== '/login') token.value = ''; throw new Error(payload.error || payload.code || '请求失败') } return payload.data as T
}
async function run(work: () => Promise<void>) { busy.value = true; error.value = ''; success.value = ''; try { await work() } catch (e) { error.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function load() { state.value = await request<State>('/state') }
async function refreshLoginChallenge() { const challenge = await request<{ mode: 'totp' | 'captcha'; challengeId?: string; imageDataUrl?: string }>('/login-challenge'); loginMode.value = challenge.mode; login.challengeId = challenge.challengeId || ''; login.captchaAnswer = ''; captchaImage.value = challenge.imageDataUrl || '' }
async function signIn() { await run(async () => { try { const result = await request<{ token: string }>('/login', login); token.value = result.token; login.password = ''; login.code = ''; login.captchaAnswer = ''; await load() } finally { if (!token.value) await refreshLoginChallenge().catch(() => {}) } }) }
async function signOut() { await run(async () => { try { await request('/logout', {}) } finally { token.value = ''; secretResult.value = ''; selected.value = null; await refreshLoginChallenge() } }) }
onMounted(() => { void run(refreshLoginChallenge) })
function packageInput(key: string) { const at = key.lastIndexOf(':'); return { packageId: key.slice(0, at), packageVersion: Number(key.slice(at + 1)) } }
async function createGrant() { await run(async () => { const result = await request<{ code: string }>('/grants', { name: issue.name, domain: issue.domain, modelMode: issue.modelMode, ...packageInput(issue.packageKey), expiresAt: issue.expiresAt ? new Date(issue.expiresAt).toISOString() : null }); secretResult.value = result.code; showIssue.value = false; await load() }) }
function edit(g: Grant) { selected.value = g; impact.value = null; change.status = g.status; change.expiresAt = ''; change.neverExpires = false; change.modelMode = g.modelMode; change.packageKey = `${g.packageId}:${state.value.packages.find(p => p.id === g.packageId)?.version || g.packageVersion}`; migration.domain = g.domain; migration.instanceId = ''; migration.overlapHours = 0 }
function closeManagement() { if (!busy.value) selected.value = null }
async function previewChange() { await run(async () => { if (!selected.value) return; pendingPatch.value = { expectedVersion: selected.value.version, status: change.status, modelMode: change.modelMode, ...packageInput(change.packageKey), ...(change.neverExpires ? { expiresAt: null } : change.expiresAt ? { expiresAt: new Date(change.expiresAt).toISOString() } : {}) }; impact.value = await request(`/grants/${encodeURIComponent(selected.value.id)}/preview`, pendingPatch.value) }) }
async function applyChange() { await run(async () => { if (!selected.value || !impact.value) return; const name = selected.value.name; await request(`/grants/${encodeURIComponent(selected.value.id)}`, { ...pendingPatch.value, previewDigest: impact.value.previewDigest }, 'PATCH'); selected.value = null; impact.value = null; await load(); success.value = `${name}的授权变更已保存，在线管理后台将在下一次同步时更新（通常60秒内）。` }) }
async function reissue(g: Grant) { await run(async () => { const result = await request<{ code: string }>(`/grants/${encodeURIComponent(g.id)}/code`, {}); secretResult.value = result.code }) }
async function rotate() { await run(async () => { if (!selected.value) return; const result = await request<{ credential: string }>(`/grants/${encodeURIComponent(selected.value.id)}/rotate`, { ...migration, expectedVersion: selected.value.version }); secretResult.value = result.credential; selected.value = null; await load() }) }
async function completeMigration() { await run(async () => { if (!selected.value) return; await request(`/grants/${encodeURIComponent(selected.value.id)}/migration/complete`, { expectedVersion: selected.value.version }); selected.value = null; await load() }) }
async function savePackage(input: LicensePackage, existing: boolean) { await run(async () => { const result = await request<{affectedGrants?:number}>(existing ? `/packages/${encodeURIComponent(input.id)}` : '/packages', { ...input, expectedVersion: input.version }, existing ? 'PATCH' : 'POST'); await load(); success.value = existing ? `“${input.name}”已保存，已更新${result.affectedGrants || 0}个授权，在线实例通常60秒内同步。` : `“${input.name}”已创建。` }) }
async function removePackage(input: LicensePackage) { await run(async () => { await request(`/packages/${encodeURIComponent(input.id)}`, { expectedVersion: input.version }, 'DELETE'); await load(); success.value = `“${input.name}”已删除，历史记录保留。` }) }
watch(() => state.value.packages, packages => { if (!packages.some(p => `${p.id}:${p.version}` === issue.packageKey)) issue.packageKey = packages[0] ? `${packages[0].id}:${packages[0].version}` : '' })
async function confirmRowAction() { await run(async () => {
  const action = rowAction.value; if (!action) return
  const grant = action.grant, path = `/grants/${encodeURIComponent(grant.id)}`
  if (action.type === 'delete') await request(path, { expectedVersion: grant.version }, 'DELETE')
  else { const patch = { expectedVersion: grant.version, status: action.type === 'enable' ? 'enabled' : 'suspended' }; const preview = await request<ChangePreview>(path+'/preview', patch); await request(path, { ...patch, previewDigest: preview.previewDigest }, 'PATCH') }
  await load(); rowAction.value = null; success.value = action.type === 'delete' ? `“${grant.name}”已删除，授权已撤销，经营数据保留。` : `“${grant.name}”已${action.type === 'enable' ? '启用' : '停用'}，在线实例通常60秒内同步。`
}) }
</script>

<template>
  <CenterLayout :authenticated="!!token" :page="page" :busy="busy" :username="login.username" @navigate="page=$event" @refresh="run(load)" @logout="signOut">
    <form v-if="!token" class="login-card login" @submit.prevent="signIn">
      <div class="login-card-heading"><span class="brand-mark brand-text-mark">羽</span><div><strong>羽枢 YushuHub</strong><span>独立授权中心</span></div></div>
      <div class="login-title"><h2>欢迎回来</h2><p>使用运营账号登录授权中心</p></div>
      <label for="operator-name">账号</label><div class="field-control"><UserRound :size="18" /><input id="operator-name" v-model="login.username" autocomplete="username" placeholder="请输入运营账号" required /></div>
      <label for="operator-password">密码</label><div class="field-control"><LockKeyhole :size="18" /><input id="operator-password" v-model="login.password" type="password" autocomplete="current-password" placeholder="请输入密码" required /></div>
      <label v-if="loginMode==='totp'" for="operator-totp">动态验证码</label><div v-if="loginMode==='totp'" class="field-control"><ShieldCheck :size="18" /><input id="operator-totp" v-model="login.code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required /></div>
      <template v-else><label for="operator-captcha">图片验证码</label><div class="login-captcha-row"><div class="field-control"><ShieldCheck :size="18" /><input id="operator-captcha" v-model="login.captchaAnswer" maxlength="5" autocomplete="off" placeholder="输入图中字符" required /></div><button class="login-captcha-image" type="button" :disabled="busy" aria-label="刷新验证码" title="看不清？点击刷新" @click="run(refreshLoginChallenge)"><img v-if="captchaImage" :src="captchaImage" alt="登录图片验证码" /><span v-else>加载验证码</span></button></div></template>
      <p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary primary-button login-button" :disabled="busy || !loginMode"><span>{{ busy ? '正在登录…' : '登录授权中心' }}</span><ArrowRight :size="18" /></button><p class="security-note">登录凭据仅用于本次会话</p>
    </form>
    <template v-else>
      <div class="page-heading"><div><span class="eyebrow">{{ page === 'grants' ? 'LICENSE MANAGEMENT' : page === 'packages' ? 'PACKAGE CONFIGURATION' : 'OPERATION AUDIT' }}</span><h1>{{ page === 'grants' ? '代理授权' : page === 'packages' ? '套餐配置' : '操作审计' }}</h1><p>{{ page === 'grants' ? '集中管理独立代理的授权、功能与部署状态。' : page === 'packages' ? '按经营需要组合功能和额度，直接编辑保存，关联授权同步生效。' : '追踪授权变更，检查到期通知的发送结果。' }}</p></div><button v-if="page==='grants'" class="primary" :disabled="busy || !state.packages.length" @click="showIssue=true"><Plus :size="17" />签发授权</button></div>
      <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p>
      <section v-if="secretResult" class="card notice"><div class="section-heading"><h2>一次性资料</h2><button @click="secretResult=''">已保存，隐藏</button></div><p>请通过受控方式交付给对应代理，关闭后不再显示。</p><code>{{ secretResult }}</code></section>
      <template v-if="page==='grants'">
        <div class="stats"><article class="metric-card"><span>代理授权</span><strong>{{ counts.total }}</strong><small>已签发的独立代理授权</small><span class="metric-icon"><KeyRound :size="20" /></span></article><article class="metric-card"><span>正常状态</span><strong>{{ counts.enabled }}</strong><small>当前有效且未暂停的授权</small><span class="metric-icon"><ShieldCheck :size="20" /></span></article><article class="metric-card"><span>固定文本模式</span><strong>{{ counts.fixed }}</strong><small>文本服务统一连接 OKPA</small><span class="metric-icon"><SlidersHorizontal :size="20" /></span></article></div>
        <section class="list-toolbar" aria-label="授权筛选"><div class="search-field"><Search :size="17" /><input v-model="search" aria-label="搜索代理" placeholder="搜索代理名称、域名或授权编号" /></div><select v-model="statusFilter" aria-label="筛选授权状态"><option value="all">全部状态</option><option value="enabled">正常</option><option value="suspended">暂停</option><option value="expired">已到期</option><option value="revoked">已撤销</option></select><button @click="search='';statusFilter='all'"><RotateCcw :size="15" />重置</button><span class="result-count">共 {{ visibleGrants.length }} 条</span></section>
        <section class="card list-card"><div class="table-scroll"><table><thead><tr><th>代理</th><th>模式 / 套餐</th><th>状态 / 期限</th><th>部署绑定</th><th class="action-column">操作</th></tr></thead><tbody><tr v-for="g in visibleGrants" :key="g.id"><td><div class="entity-cell"><span class="entity-icon"><KeyRound :size="18" /></span><div><strong>{{ g.name }}</strong><small>{{ g.id }}</small></div></div></td><td>{{ modeLabel(g.modelMode) }}<small>{{ packageLabel(state.packages,g.packageId,g.packageVersion) }}</small></td><td><span class="status-badge" :class="g.status === 'enabled' && g.expiresAt && Date.parse(g.expiresAt) <= Date.now() ? 'expired' : g.status">{{ statusLabel(g.status === 'enabled' && g.expiresAt && Date.parse(g.expiresAt) <= Date.now() ? 'expired' : g.status) }}</span><small>{{ g.expiresAt ? new Date(g.expiresAt).toLocaleString('zh-CN') : '不限期' }}</small></td><td class="binding-cell">{{ g.domain }}<small>{{ g.instanceId || '未激活' }}</small></td><td><div class="row-actions"><button class="text-button" :disabled="busy || g.status==='revoked'" @click="edit(g)">管理</button><button v-if="g.status!=='revoked'" class="text-button" :disabled="busy" @click="rowAction={grant:g,type:g.status==='suspended'?'enable':'suspend'}">{{ g.status==='suspended' ? '启用' : '停用' }}</button><button class="text-button danger" :disabled="busy" @click="rowAction={grant:g,type:'delete'}">删除</button><button v-if="!g.instanceId && g.status!=='revoked'" class="text-button" :disabled="busy" @click="reissue(g)">重发激活码</button></div></td></tr><tr v-if="!visibleGrants.length"><td colspan="5" class="empty-state"><KeyRound :size="28" /><strong>{{ state.grants.length ? '没有符合条件的授权' : '尚未签发代理授权' }}</strong><span>{{ state.grants.length ? '请调整搜索关键词或状态筛选。' : '点击右上方“签发授权”创建第一份授权。' }}</span></td></tr></tbody></table></div></section>
      </template>
      <PackageEditor v-if="page==='packages'" :packages="state.packages" :groups="state.capabilityGroups" :busy="busy" :message="success" :error-message="error" @save="savePackage" @remove="removePackage" />
      <template v-if="page==='audit'"><section class="card"><div class="section-heading"><h2>到期通知</h2><span class="muted">{{ state.notices.length }} 条记录</span></div><p v-if="!state.notices.length" class="empty-note">尚无到期提醒，授权临近到期时会在此显示。</p><div v-for="n in state.notices" :key="n.id" class="notice-row"><span>{{ n.grantName || '历史代理' }}<small>到期前 {{ n.days }} 天</small></span><span class="status-badge" :class="n.deliveredAt ? 'enabled' : 'suspended'">{{ n.cancelledAt ? '已取消' : n.deliveredAt ? '已发送' : n.lastError ? '发送失败，等待重试' : '等待通知发送' }}</span></div></section><section class="card list-card"><div class="section-heading list-heading"><h2>最近操作</h2><span class="muted">{{ state.audit.length }} 条记录</span></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>对象 / 说明</th></tr></thead><tbody><tr v-for="a in state.audit" :key="a.id"><td>{{ new Date(a.at).toLocaleString('zh-CN') }}</td><td>{{ a.actorLabel }}</td><td>{{ a.eventLabel }}</td><td><strong>{{ a.targetLabel }}</strong><small>{{ a.description }}</small></td></tr><tr v-if="!state.audit.length"><td colspan="4" class="empty-note">暂无操作记录</td></tr></tbody></table></div></section></template>
      <dialog v-if="rowAction" ref="actionDialog" class="grant-dialog package-delete-dialog" aria-labelledby="grant-action-title" @cancel.prevent="!busy && (rowAction=null)"><div class="section-heading"><h2 id="grant-action-title">{{ rowAction.type==='delete' ? '删除代理授权' : rowAction.type==='enable' ? '启用代理授权' : '停用代理授权' }}</h2><button :disabled="busy" @click="rowAction=null">关闭</button></div><p>代理：{{ rowAction.grant.name }}</p><p v-if="rowAction.type==='delete'">删除后授权立即撤销，并从列表移除；此操作不能恢复。代理经营后台的用户、订单和历史数据不会删除，审计记录继续保留。</p><p v-else-if="rowAction.type==='suspend'">停用后将阻止新的经营请求，在线实例通常60秒内同步。已有数据和累计用量保留，可随时重新启用。</p><p v-else>启用后恢复正常授权状态；仍需满足原有到期时间和部署绑定要求，已到期授权需先续期。</p><p v-if="error" class="error" role="alert">{{ error }}</p><div class="dialog-actions"><button :disabled="busy" @click="rowAction=null">取消</button><button class="primary" :class="{'danger-button':rowAction.type==='delete'}" :disabled="busy" @click="confirmRowAction">{{ rowAction.type==='delete' ? '确认删除授权' : rowAction.type==='enable' ? '确认启用' : '确认停用' }}</button></div></dialog>
      <dialog v-if="showIssue" ref="issueDialog" class="grant-dialog issue-dialog" aria-labelledby="issue-title" @cancel.prevent="!busy && (showIssue=false)"><div class="section-heading"><div><h2 id="issue-title">签发独立代理授权</h2><p>为独立部署的代理配置资格与功能。</p></div><button :disabled="busy" @click="showIssue=false">关闭</button></div><p v-if="error" class="error" role="alert">{{ error }}</p><form class="grid" @submit.prevent="createGrant"><label>代理名称<input v-model="issue.name" required /></label><label>部署域名<input v-model="issue.domain" type="url" placeholder="https://agent.example.com" required /></label><label>功能套餐<select v-model="issue.packageKey"><option v-for="p in state.packages" :key="p.id+':'+p.version" :value="p.id+':'+p.version">{{ p.name }}</option></select></label><label>文本供应商<select v-model="issue.modelMode"><option value="fixed">固定 OKPA API</option><option value="custom">自定义服务商</option></select></label><label>到期时间（留空不限期）<input v-model="issue.expiresAt" type="datetime-local" /></label><button class="primary" :disabled="busy">签发一次性激活码</button></form></dialog>
      <dialog v-if="selected" ref="managementDialog" class="grant-dialog" aria-labelledby="grant-dialog-title" @cancel.prevent="closeManagement">
        <div class="section-heading"><h2 id="grant-dialog-title">管理授权：{{ selected.name }}</h2><button :disabled="busy" @click="closeManagement">关闭</button></div>
        <p>修改只影响当前代理。固定／自定义服务商与功能套餐分别设置；已有用户权益和累计用量保持。</p>
        <p v-if="error" class="error" role="alert">{{ error }}</p>
        <form @submit.prevent="previewChange"><fieldset class="grid package-controls" :disabled="busy">
          <label>授权状态<select v-model="change.status"><option value="enabled">正常</option><option value="suspended">暂停</option><option value="revoked">撤销（不可恢复）</option></select></label>
          <label>文本服务商模式<select v-model="change.modelMode"><option value="fixed">固定 OKPA API</option><option value="custom">允许自定义服务商</option></select></label>
          <label>功能套餐<select v-model="change.packageKey"><option v-for="p in state.packages" :key="p.id+':'+p.version" :value="p.id+':'+p.version">{{ packageLabel(state.packages,p.id,p.version) }}</option></select></label>
          <label class="checkbox-line"><input v-model="change.neverExpires" type="checkbox" />改为不限期</label>
          <label>新到期时间（留空保持）<input v-model="change.expiresAt" type="datetime-local" :disabled="change.neverExpires" /></label>
          <button :disabled="busy">预览变更</button>
        </fieldset></form>
        <GrantChangePreview v-if="impact" :preview="impact" :packages="state.packages" :groups="state.capabilityGroups" />
        <p v-else class="muted">修改配置后，先点击“预览变更”核对，再确认保存。</p>
        <div class="grant-save"><p>确认保存后，在线代理后台通常在60秒内同步新授权。</p><button class="primary" :disabled="busy || !impact" @click="applyChange">确认保存授权变更</button></div>
        <details class="migration-settings"><summary>部署迁移（高级操作）</summary><form class="grid" @submit.prevent="rotate"><label>新实例ID<input v-model="migration.instanceId" required /></label><label>新域名<input v-model="migration.domain" type="url" required /></label><label>双实例小时（0–24）<input v-model.number="migration.overlapHours" type="number" min="0" max="24" /></label><button :disabled="busy">轮换实例凭据</button></form><button :disabled="busy" @click="completeMigration">提前撤销旧实例访问</button></details>
      </dialog>
    </template>
  </CenterLayout>
</template>
